        const bundle_until_now = @divTrunc(@as(i64, @truncate((bundled_end - bun.cli.start_time))), (if (comptime @typeInfo(@TypeOf(std.time.ns_per_ms)) == .@"enum") cp_cast_int(i64, @intFromEnum(std.time.ns_per_ms)) else cp_cast_int(i64, std.time.ns_per_ms)));
        const bundle_elapsed = (if (minified) (bundle_until_now - (if (comptime @typeInfo(@TypeOf((if (comptime @typeInfo(@TypeOf(@as(u63, @truncate(minify_duration)))) == .@"enum") cp_cast_int(i32, @intFromEnum(@as(u63, @truncate(minify_duration)))) else cp_cast_int(i32, @as(u63, @truncate(minify_duration)))))) == .@"enum") cp_cast_int(i64, @intFromEnum((if (comptime @typeInfo(@TypeOf(@as(u63, @truncate(minify_duration)))) == .@"enum") cp_cast_int(i32, @intFromEnum(@as(u63, @truncate(minify_duration)))) else cp_cast_int(i32, @as(u63, @truncate(minify_duration)))))) else cp_cast_int(i64, (if (comptime @typeInfo(@TypeOf(@as(u63, @truncate(minify_duration)))) == .@"enum") cp_cast_int(i32, @intFromEnum(@as(u63, @truncate(minify_duration)))) else cp_cast_int(i32, @as(u63, @truncate(minify_duration))))))) else bundle_until_now);
        const minified_digit_count: usize = (switch (minify_duration) {
0...9 => 3,
10...99 => 2,
100...999 => 1,
1000...9999 => 0,
else => 0,
});
        if (minified) {
            _ = Output.pretty("{s}", .{ padding_buf[0..(if (comptime @typeInfo(@TypeOf((if (comptime @typeInfo(@TypeOf(minified_digit_count)) == .@"enum") cp_cast_int(i32, @intFromEnum(minified_digit_count)) else cp_cast_int(i32, minified_digit_count)))) == .@"enum") cp_cast_int(usize, @intFromEnum((if (comptime @typeInfo(@TypeOf(minified_digit_count)) == .@"enum") cp_cast_int(i32, @intFromEnum(minified_digit_count)) else cp_cast_int(i32, minified_digit_count)))) else cp_cast_int(usize, (if (comptime @typeInfo(@TypeOf(minified_digit_count)) == .@"enum") cp_cast_int(i32, @intFromEnum(minified_digit_count)) else cp_cast_int(i32, minified_digit_count))))] });
            _ = Output.printElapsedStdoutTrim(@as(f64, @floatFromInt(minify_duration)));
            const output_size = brk: {
            var total_size: u64 = 0;
            _ = &total_size;
            for (cp_mut_slice(&output_files)) |*f| {
                _ = &f;
                if (((f.*).loader == .js)) {
                    total_size = (total_size + (f.*).size_without_sourcemap);
                }
            }
            break :brk total_size;
};
            const delta: i64 = @as(i64, @truncate(((if (comptime @typeInfo(i65) == .@"enum") @as(i65, @enumFromInt((if (comptime @typeInfo(@TypeOf(input_code_length)) == .@"enum") cp_cast_int(i32, @intFromEnum(input_code_length)) else cp_cast_int(i32, input_code_length)))) else @as(i65, (if (comptime @typeInfo(@TypeOf(input_code_length)) == .@"enum") cp_cast_int(i32, @intFromEnum(input_code_length)) else cp_cast_int(i32, input_code_length)))) - (if (comptime @typeInfo(i65) == .@"enum") @as(i65, @enumFromInt((if (comptime @typeInfo(@TypeOf(output_size)) == .@"enum") cp_cast_int(i32, @intFromEnum(output_size)) else cp_cast_int(i32, output_size)))) else @as(i65, (if (comptime @typeInfo(@TypeOf(output_size)) == .@"enum") cp_cast_int(i32, @intFromEnum(output_size)) else cp_cast_int(i32, output_size)))))));
            if ((delta > 1024)) {
                _ = Output.prettyln("  <green>minify<r>  -{f} <d>(estimate)<r>", .{ bun.fmt.size((if (comptime @typeInfo(@TypeOf((if (comptime @typeInfo(@TypeOf(delta)) == .@"enum") cp_cast_int(i32, @intFromEnum(delta)) else cp_cast_int(i32, delta)))) == .@"enum") cp_cast_int(usize, @intFromEnum((if (comptime @typeInfo(@TypeOf(delta)) == .@"enum") cp_cast_int(i32, @intFromEnum(delta)) else cp_cast_int(i32, delta)))) else cp_cast_int(usize, (if (comptime @typeInfo(@TypeOf(delta)) == .@"enum") cp_cast_int(i32, @intFromEnum(delta)) else cp_cast_int(i32, delta)))), .{}) });
            } else {
                if (((0 - delta) > 1024)) {
                    _ = Output.prettyln("  <b>minify<r>   +{f} <d>(estimate)<r>", .{ bun.fmt.size((if (comptime @typeInfo(@TypeOf((if (comptime @typeInfo(@TypeOf((0 - delta))) == .@"enum") cp_cast_int(i32, @intFromEnum((0 - delta))) else cp_cast_int(i32, (0 - delta))))) == .@"enum") cp_cast_int(usize, @intFromEnum((if (comptime @typeInfo(@TypeOf((0 - delta))) == .@"enum") cp_cast_int(i32, @intFromEnum((0 - delta))) else cp_cast_int(i32, (0 - delta))))) else cp_cast_int(usize, (if (comptime @typeInfo(@TypeOf((0 - delta))) == .@"enum") cp_cast_int(i32, @intFromEnum((0 - delta))) else cp_cast_int(i32, (0 - delta))))), .{}) });
                } else {
                    _ = Output.prettyln("  <b>minify<r>", .{});
                }
            }
        }
        const bundle_elapsed_digit_count: usize = (switch (bundle_elapsed) {
0...9 => 3,
10...99 => 2,
100...999 => 1,
1000...9999 => 0,
else => 0,
});
        _ = Output.pretty("{s}", .{ padding_buf[0..(if (comptime @typeInfo(@TypeOf((if (comptime @typeInfo(@TypeOf(bundle_elapsed_digit_count)) == .@"enum") cp_cast_int(i32, @intFromEnum(bundle_elapsed_digit_count)) else cp_cast_int(i32, bundle_elapsed_digit_count)))) == .@"enum") cp_cast_int(usize, @intFromEnum((if (comptime @typeInfo(@TypeOf(bundle_elapsed_digit_count)) == .@"enum") cp_cast_int(i32, @intFromEnum(bundle_elapsed_digit_count)) else cp_cast_int(i32, bundle_elapsed_digit_count)))) else cp_cast_int(usize, (if (comptime @typeInfo(@TypeOf(bundle_elapsed_digit_count)) == .@"enum") cp_cast_int(i32, @intFromEnum(bundle_elapsed_digit_count)) else cp_cast_int(i32, bundle_elapsed_digit_count))))] });
        _ = Output.printElapsedStdoutTrim(@as(f64, @floatFromInt(bundle_elapsed)));
        _ = Output.prettyln("  <green>bundle<r>  {d} modules", .{ reachable_file_count });
}
